<?php $edit = $edit ?? null;
$assigned = [];
if ($edit) foreach ($app->storage->read('role_permissions.csv', ['role_id', 'permission_id']) as $row) if ($row['role_id'] === $edit['id']) $assigned[] = $row['permission_id']; ?><h1><?= $edit ? 'Editar perfil' : 'Novo perfil' ?></h1>
<form method="post" action="<?= $edit ? '/admin/roles/' . e($edit['id']) : '/admin/roles' ?>"><input type="hidden" name="_csrf" value="<?= e($csrf) ?>"><?php if ($edit): ?><input type="hidden" name="_method" value="PATCH"><?php endif; ?><label>Nome <input name="name" value="<?= e($edit['name'] ?? '') ?>" <?= $edit && $edit['id'] === 'role_dev' ? 'readonly' : 'required' ?>></label><label>Descrição <textarea name="description"><?= e($edit['description'] ?? '') ?></textarea></label><label>Permissões</label><?php foreach ($permissions as $permission): ?><label><input type="checkbox" name="permissions[]" value="<?= e($permission['id']) ?>" <?= in_array($permission['id'], $assigned, true) ? 'checked' : '' ?>> <?= e($permission['name']) ?></label><?php endforeach; ?><button type="submit">Salvar</button></form>